"""HTTP transport — connects to a remote Strata MCP server via Streamable HTTP."""

from __future__ import annotations

from typing import Any

from mcp import ClientSession
from mcp.client.streamable_http import streamablehttp_client

from strata.exceptions import (
    StrataConnectionError,
    StrataProtocolError,
    StrataTimeoutError,
)
from strata.transport.base import Transport


class HttpTransport(Transport):
    """Connects to a Strata HTTP/SSE endpoint via MCP Streamable HTTP transport."""

    def __init__(
        self,
        url: str,
        token: str | None = None,
        timeout: float = 30.0,
    ) -> None:
        self._url = url
        self._token = token
        self._timeout = timeout
        self._session: ClientSession | None = None
        self._context_stack: list[Any] = []

    async def connect(self) -> None:
        if self._session is not None:
            return

        headers: dict[str, str] = {}
        if self._token:
            headers["Authorization"] = f"Bearer {self._token}"

        try:
            cm = streamablehttp_client(self._url, headers=headers)
            streams = await cm.__aenter__()
            self._context_stack.append(cm)

            session = ClientSession(*streams)
            await session.__aenter__()
            self._context_stack.append(session)

            await session.initialize()
            self._session = session
        except TimeoutError as exc:
            await self._cleanup_stack()
            raise StrataTimeoutError(
                f"Timed out connecting to {self._url}"
            ) from exc
        except Exception as exc:
            await self._cleanup_stack()
            raise StrataConnectionError(
                f"Failed to connect to {self._url}: {exc}"
            ) from exc

    async def call_tool(self, name: str, arguments: dict[str, Any]) -> str:
        if self._session is None:
            raise StrataConnectionError("Not connected. Call connect() first.")

        try:
            result = await self._session.call_tool(name, arguments)
        except TimeoutError as exc:
            raise StrataTimeoutError(f"Tool call '{name}' timed out") from exc
        except Exception as exc:
            raise StrataProtocolError(f"Tool call '{name}' failed: {exc}") from exc

        parts: list[str] = []
        for content in result.content:
            if hasattr(content, "text"):
                parts.append(content.text)
        if not parts:
            raise StrataProtocolError(f"Empty response from tool '{name}'", raw_response=str(result))
        return "\n".join(parts)

    async def close(self) -> None:
        self._session = None
        await self._cleanup_stack()

    async def _cleanup_stack(self) -> None:
        while self._context_stack:
            cm = self._context_stack.pop()
            try:
                await cm.__aexit__(None, None, None)
            except Exception:
                pass
